			needsRebuild := !indexCurrent || !verifyAvailable || !verify.Clean || !receiptsCurrent || !fingerprintCurrent
			if sessionRef != "" {
				digest, scopeErr := canonicalSessionInputDigest(brainDir, manifest, sessionRef)
				if scopeErr != nil {
