		return err
	}
	if err := os.MkdirAll(filepath.Dir(final), 0o700); err != nil {
		return err
	}
	if err := validateHistoryProjectionDirectory(outputDir, prepared.stagingDir, true); err != nil {
		return fmt.Errorf("validate staged history generation: %w", err)
	}
