// brain that was never built (`setup`) or for a corrupt store (`doctor`).
const statusRemedyRefresh = "refresh --agent none"

// buildStatusHealth counts everything a reader would call a problem.
func buildStatusHealth(report brainStatusReport) statusHealth {
	health := statusHealth{
		Issues:   len(report.Issues),
		Warnings: len(report.Warnings) + len(report.Live.Warnings),
		Severity: brainStatusFreshnessSeverity(report),
		// "absent" is inspectBrainManifestHealth's own word for a brain that
		// was never built (and for one just removed by `reset --force`).
		BrainMissing: report.Brain.ManifestState == "absent",
		Cause:        statusFreshnessCause(report),
	}
	// Only one of the two: "no brain" already implies "no semantic index", and
	// a verdict that said both would be reporting one fact twice.
	health.SemanticMissing = !health.BrainMissing && report.Semantic == nil
	if report.Onboarding != nil {
		health.HostCLIMissing = report.Onboarding.HostCLIMissing
		for _, component := range report.Onboarding.Components {
			if component.State == "failed" {
				health.Failed = append(health.Failed, component.Name)
				if setupIsNoReadableSessions(component.Detail) {
					health.NoCapturedSessions = true
				}
			}
		}
	}
	// The live worktree, not a freshness axis. The `dirty-unindexed` axis is one
	// SYMPTOM of a dirty tree and it was the obvious thing to key on, but it is
	// not the condition: after `refresh --worktree` the seed axis reads
	// `dirty-indexed` and freshness aggregates to "ok", while `refresh --agent
	// none` goes on refusing to reseed the same uncommitted content. Asking the
	// working tree directly covers both.
	health.DirtyWorktree = report.Live.Dirty
	return health
	}
	minor, err := strconv.Atoi(minorText)
	if err != nil || minor < 0 {
		return 0, 0, fmt.Errorf("semantic schema version %q has a non-numeric minor", version)
	}
	return major, minor, nil
}

// validateSemanticSchema applies ADR 0001's compatibility boundary: refuse an
// unknown major, accept every minor within the supported major.
func validateSemanticSchema(version string) error {
	major, _, err := parseSemanticSchemaVersion(version)
	if err != nil {
		return fmt.Errorf("%w (this build reads %s)", err, semanticSupportedSchemaRange)
	}
	if strconv.Itoa(major) != semanticSupportedMajor {
		return fmt.Errorf("unsupported semantic schema major version %q: this build reads %s", strconv.Itoa(major), semanticSupportedSchemaRange)
	}
	return nil
}

// semanticSchemaMinorSkewWarning implements ADR 0001 rule 3: a newer minor
// within the supported major is accepted, but the reader must WARN, because the
// producer may have emitted additive facts this build does not know how to
// ingest. Accepting silently is not compliance — the whole point of the warning
// is that the resulting index is quietly less complete than the snapshot.
//
// This is the single implementation of that rule, applied at every place a
// schema_version crosses into this build alongside validateSemanticSchema:
//
//  1. runSemanticIndex — a live `entire graph snapshot` header, recorded as an
//     index warning on the persisted manifest;
//  2. semanticStaleReport — the "provider" freshness axis reported by brain
//     doctor/status and every semantic read command, degraded rather than ok;
//  3. validateImportedBundle — an imported bundle manifest, warning appended to
//     the semantic source that is then persisted.
//
// It returns nil for an unparseable or non-supported-major version:
// validateSemanticSchema is the sole authority on rejecting those outright, and
// each call site runs it first.
func semanticSchemaMinorSkewWarning(version string) *semanticWarning {
	major, minor, err := parseSemanticSchemaVersion(version)
	if err != nil {
		return nil
	}
	knownMajor, knownMinor, err := parseSemanticSchemaVersion(semanticSchemaVersion)
	if err != nil || strconv.Itoa(major) != semanticSupportedMajor || minor <= knownMinor || major != knownMajor {
		return nil
	}
	return &semanticWarning{
		Code:     "provider_schema_newer_minor",
		Severity: "warning",
		Effect:   "additive semantic facts introduced after " + semanticSchemaVersion + " may not have been ingested",
		// Kept under statusCauseWidth: this Detail is rendered inside the
		// one-line status cause, and the longer wording was cut mid-word
		// ("...so the snapshot is usabl") in the short report.
		Detail: fmt.Sprintf(
			"provider schema_version %q is newer than this build's %s; minors are additive, so the snapshot is usable -- upgrade to ingest everything",
			version, semanticSchemaVersion),
	}
}

// semanticBuildCancelCheckEvery / semanticBuildCancelCheckEveryFile are how
// often the store build asks whether its deadline has passed. Both are small
// enough that a cancelled MCP index stops within a fraction of a second and
// large enough that the check itself is free.
