1	package cli
2	
3	import (
4		"errors"
5		"fmt"
6		"io"
7		"os"
8		"path/filepath"
9		"strconv"
10		"strings"
11		"sync"
12		"time"
13	)
14	
15	const fileLockRetryInterval = 10 * time.Millisecond
16	
17	var errFileLockTimeout = errors.New("file lock timeout")
18	
19	// errFileHardlinked classifies the nlink>1 refusal so callers can tell an
20	// externally hardlinked state file (a backup or bench tool's cheap copy, which
21	// a rebuild clears) from damage that needs different handling. The rendered
22	// message is unchanged: "<label> must not be hardlinked: <path>".
23	var errFileHardlinked = errors.New("must not be hardlinked")
24	
25	type fileLock struct {
26		path        string
27		file        *os.File
28		processLock *processFileLock
29	}
30	
31	// processFileLocks makes file locks visible to Go goroutines for the full
32	// acquireFileLock-to-Close lifetime. The OS lock remains necessary for other
33	// processes.
34	var processFileLocks processFileLockRegistry
35	
36	type processFileLockRegistry struct {
37		sync.Mutex
38		// os.FileInfo has no portable comparable identity, so lookup uses os.SameFile.
39		locks []*processFileLock
40	}
41	
42	type processFileLock struct {
43		parent   os.FileInfo
44		basename string
45		token    chan struct{}
46		refs     int // holders and waiters; protected by processFileLocks
47	}
48	
49	func acquireFileLock(path, code string, timeout time.Duration) (*fileLock, error) {
50		if err := os.MkdirAll(filepath.Dir(path), 0o700); err != nil {
51			return nil, fmt.Errorf("create lock directory: %w", err)
52		}
53		parent, basename, err := fileLockIdentity(path)
54		if err != nil {
55			return nil, err
56		}
57		deadline := time.Now().Add(timeout)
58		processLock, ok := acquireProcessFileLock(parent, basename, deadline, timeout)
59		if !ok {
60			return nil, fileLockTimeoutError(code, path)
61		}
62		defer func() {
63			if processLock != nil {
64				processLock.release()
65			}
66		}()
67	
68		for {
69			if err := rejectUnsafeExistingRegularFile(path, "lock file"); err != nil {
70				return nil, err
71			}
72			f, err := os.OpenFile(path, os.O_CREATE|os.O_RDWR|fileLockOpenFlags(), 0o600)
73			if err != nil {
74				return nil, fmt.Errorf("open lock file: %w", err)
75			}
76			if err := rejectOpenFileAlias(path, f, "lock file"); err != nil {
77				_ = f.Close()
78				return nil, err
79			}
80			err = tryLockFile(f)
81			if err == nil {
82				writeLockOwnerMetadata(path)
83				lock := &fileLock{path: path, file: f, processLock: processLock}
84				processLock = nil
85				return lock, nil
86			}
87			_ = f.Close()
88			if !isLockBusy(err) {
89				return nil, fmt.Errorf("lock file: %w", err)
90			}
91			if timeout <= 0 || time.Now().Add(fileLockRetryInterval).After(deadline) {
92				return nil, fileLockTimeoutError(code, path)
93			}
94			time.Sleep(fileLockRetryInterval)
95		}
96	}
97	
98	func fileLockIdentity(path string) (os.FileInfo, string, error) {
99		parent, err := os.Stat(filepath.Dir(path))
100		if err != nil {
101			return nil, "", fmt.Errorf("stat lock directory: %w", err)
102		}
103		if !parent.IsDir() {
104			return nil, "", fmt.Errorf("lock directory must be a directory: %s", filepath.Dir(path))
105		}
106		return parent, filepath.Base(path), nil
107	}
108	
109	func acquireProcessFileLock(parent os.FileInfo, basename string, deadline time.Time, timeout time.Duration) (*processFileLock, bool) {
110		processFileLocks.Lock()
111		lock := processFileLocks.find(parent, basename)
112		if lock == nil {
113			lock = &processFileLock{parent: parent, basename: basename, token: make(chan struct{}, 1)}
114			processFileLocks.locks = append(processFileLocks.locks, lock)
115		}
116		lock.refs++
117		processFileLocks.Unlock()
118	
119		select {
120		case lock.token <- struct{}{}:
121			return lock, true
122		default:
123		}
124		if timeout <= 0 {
125			lock.releaseReference()
126			return nil, false
127		}
128		remaining := time.Until(deadline)
129		if remaining <= 0 {
130			lock.releaseReference()
131			return nil, false
132		}
133		timer := time.NewTimer(remaining)
134		defer timer.Stop()
135		select {
136		case lock.token <- struct{}{}:
137			return lock, true
138		case <-timer.C:
139			lock.releaseReference()
140			return nil, false
141		}
142	}
143	
144	func (l *processFileLock) release() {
145		<-l.token
146		l.releaseReference()
147	}
148	
149	func (r *processFileLockRegistry) find(parent os.FileInfo, basename string) *processFileLock {
150		for _, lock := range r.locks {
151			if lock.basename == basename && os.SameFile(lock.parent, parent) {
152				return lock
153			}
154		}
155		return nil
156	}
157	
158	func (l *processFileLock) releaseReference() {
159		processFileLocks.Lock()
160		defer processFileLocks.Unlock()
161		l.refs--
162		if l.refs != 0 {
